import pandas as pd
import numpy as np


def _segments_differ(a, b):
    a_na = pd.isna(a)
    b_na = pd.isna(b)
    if a_na and b_na:
        return False
    if a_na != b_na:
        return True
    return a != b


def _get_input(inputs: dict, name: str) -> pd.DataFrame:
    # Try exact match first
    if name in inputs:
        return inputs[name]
    # Try case-insensitive match
    lname = name.lower()
    for k, v in inputs.items():
        if k.lower() == lname:
            return v
    raise KeyError(f"Could not find input matching '{name}' among {list(inputs.keys())}")


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, "DIM_CUSTOMER").copy()
    stg = _get_input(inputs, "STG_CUSTOMER").copy()
    fact = _get_input(inputs, "FACT_TXN").copy()

    # Ensure proper dtypes for dates
    for col in ["eff_start_date", "eff_end_date"]:
        if col in dim.columns:
            dim[col] = pd.to_datetime(dim[col], errors="coerce")
    if "update_date" in stg.columns:
        stg["update_date"] = pd.to_datetime(stg["update_date"], errors="coerce")
    if "txn_date" in fact.columns:
        fact["txn_date"] = pd.to_datetime(fact["txn_date"], errors="coerce")

    # Determine current rows per customer_id (assume at most one current row per customer)
    current_rows = dim[dim["is_current"] == 1].copy()
    current_map = {}
    for idx, row in current_rows.iterrows():
        current_map[row["customer_id"]] = (idx, row["segment"])

    # Determine max surrogate key before load
    if len(dim) > 0:
        max_sk = dim["customer_sk"].max()
    else:
        max_sk = 0

    # Sort staged records by customer_id for deterministic row_number assignment
    stg_sorted = stg.sort_values(by="customer_id", kind="mergesort").reset_index(drop=True)

    creates = []  # list of (customer_id, segment, update_date, prior_idx_or_none)
    for _, srow in stg_sorted.iterrows():
        cid = srow["customer_id"]
        seg = srow["segment"]
        upd = srow["update_date"]

        if cid in current_map:
            prior_idx, prior_seg = current_map[cid]
            if _segments_differ(prior_seg, seg):
                creates.append((cid, seg, upd, prior_idx))
        else:
            creates.append((cid, seg, upd, None))

    # Assign surrogate keys in order of customer_id (already sorted)
    new_rows = []
    sk_counter = max_sk
    for cid, seg, upd, prior_idx in creates:
        sk_counter += 1
        new_sk = sk_counter

        # Expire prior current row if exists
        if prior_idx is not None:
            dim.at[prior_idx, "eff_end_date"] = upd
            dim.at[prior_idx, "is_current"] = 0

        new_rows.append({
            "customer_sk": new_sk,
            "customer_id": cid,
            "segment": seg,
            "eff_start_date": upd,
            "eff_end_date": pd.NaT,
            "is_current": 1
        })

    if new_rows:
        new_df = pd.DataFrame(new_rows)
        dim = pd.concat([dim, new_df], ignore_index=True)

    # Ensure proper dtypes
    dim["customer_sk"] = dim["customer_sk"].astype(int)
    dim["customer_id"] = dim["customer_id"].astype(int)
    dim["is_current"] = dim["is_current"].astype(int)

    dim_customer_out = dim.reset_index(drop=True)

    # ---- STEP 2: Key the facts against the updated dimension ----

    dim_for_join = dim_customer_out[["customer_sk", "customer_id", "eff_start_date", "eff_end_date"]].copy()

    merged = fact.merge(dim_for_join, on="customer_id", how="left", suffixes=("", "_dim"))

    def covers(row):
        if pd.isna(row["customer_sk"]):
            return False
        start = row["eff_start_date"]
        end = row["eff_end_date"]
        txn_date = row["txn_date"]
        if pd.isna(start):
            return False
        if txn_date < start:
            return False
        if pd.isna(end):
            return True
        return txn_date < end

    if len(merged) > 0:
        mask = merged.apply(covers, axis=1)
        matched = merged[mask].copy()
    else:
        matched = merged.copy()
        matched["customer_sk"] = np.nan

    # For each txn_id, there should be at most one matching version; take first if multiple
    if len(matched) > 0:
        matched_dedup = matched.sort_values(by=["txn_id", "customer_sk"]).drop_duplicates(subset=["txn_id"], keep="first")
    else:
        matched_dedup = matched

    fact_result = fact.merge(
        matched_dedup[["txn_id", "customer_sk"]],
        on="txn_id",
        how="left"
    )

    fact_result["customer_sk"] = fact_result["customer_sk"].fillna(-1).astype(int)

    fact_txn_keyed = fact_result[["txn_id", "customer_sk", "amount"]].copy()

    return {
        "dim_customer_out": dim_customer_out,
        "fact_txn_keyed": fact_txn_keyed
    }
